package ro.leo.visual;
import android.app.*;import android.content.*;import android.database.Cursor;import android.media.*;import android.net.Uri;import android.os.Bundle;import java.util.*;
/** Native keypad tone picker; preview is explicit and stopped on departure. */
public final class SoundSettingsActivity extends LeoActivity {
    private Ringtone preview;private int selected;private final android.os.Handler timer=new android.os.Handler();private final Runnable endPreview=new Runnable(){public void run(){stopPreview();}};
    protected void onResume(){super.onResume();show();}
    protected void onPause(){stopPreview();super.onPause();}
    private void stopPreview(){timer.removeCallbacks(endPreview);if(preview!=null){preview.stop();preview=null;}}
    private String tone(int type){Uri uri=RingtoneManager.getActualDefaultRingtoneUri(this,type);if(uri==null)return type==RingtoneManager.TYPE_ALARM?"Ton de rezervă":"Silențios";try{Ringtone ringtone=RingtoneManager.getRingtone(this,uri);return ringtone==null?"Indisponibil":ringtone.getTitle(this);}catch(RuntimeException e){return "Indisponibil";}}
    private void show(){list("Sunete Leo",Arrays.asList("Profil · "+SoundProfiles.current(this),"Volume separate","Apel · "+tone(RingtoneManager.TYPE_RINGTONE),"Notificări · "+tone(RingtoneManager.TYPE_NOTIFICATION),"Alarmă · "+tone(RingtoneManager.TYPE_ALARM),"Nu deranjați","Programare Noapte / Silențios"),selected,new Choice(){public void pick(int i){selected=i;if(i==6)startActivity(new Intent(SoundSettingsActivity.this,SoundScheduleActivity.class));else if(i==0)SoundProfiles.select(SoundSettingsActivity.this,new Runnable(){public void run(){show();}});else if(i==1)startActivity(new Intent(SoundSettingsActivity.this,QuickSettingsActivity.class).putExtra("volumes",true));else if(i<5)tones(new int[]{RingtoneManager.TYPE_RINGTONE,RingtoneManager.TYPE_NOTIFICATION,RingtoneManager.TYPE_ALARM}[i-2]);else dnd();}},"",null);}
    private void tones(final int type){stopPreview();begin("Tonuri · se încarcă");root.addView(text("Se citește biblioteca Android…",17));footer("","","Înapoi");worker.execute(new Runnable(){public void run(){final ArrayList<String> names=new ArrayList<String>();final ArrayList<Uri> sources=new ArrayList<Uri>();if(type!=RingtoneManager.TYPE_ALARM){names.add("Silențios");sources.add(null);}RingtoneManager manager=new RingtoneManager(SoundSettingsActivity.this);try{manager.setType(type);Cursor cursor=manager.getCursor();if(cursor!=null)try{while(cursor.moveToNext()&&names.size()<201){sources.add(manager.getRingtoneUri(cursor.getPosition()));names.add(cursor.getString(RingtoneManager.TITLE_COLUMN_INDEX));}}finally{cursor.close();}}catch(RuntimeException denied){}ui(new Runnable(){public void run(){list("Alege tonul",names,0,new Choice(){public void pick(final int at){options(names.get(at),new String[]{"Aplică tonul","Ascultă proba","Oprește proba"},new Choice(){public void pick(int command){if(command==0){stopPreview();try{RingtoneManager.setActualDefaultRingtoneUri(SoundSettingsActivity.this,type,sources.get(at));notice("Ton salvat");show();}catch(RuntimeException denied){notice("Tonul nu poate fi schimbat");}}else if(command==2)stopPreview();else{stopPreview();if(sources.get(at)==null){notice("Ton silențios");return;}try{preview=RingtoneManager.getRingtone(SoundSettingsActivity.this,sources.get(at));if(preview!=null){preview.play();timer.postDelayed(endPreview,8000);}}catch(RuntimeException failed){notice("Proba nu poate fi redată");}}}});}},"Înapoi",new Runnable(){public void run(){stopPreview();show();}});back=new Runnable(){public void run(){stopPreview();show();}};}});}});}
    private void dnd(){final NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(!nm.isNotificationPolicyAccessGranted()){notice("Acces Nu deranjați neacordat");return;}options("Nu deranjați",new String[]{"Oprit","Doar prioritare","Doar alarme","Fără întreruperi, inclusiv alarme"},new Choice(){public void pick(int i){try{nm.setInterruptionFilter(new int[]{NotificationManager.INTERRUPTION_FILTER_ALL,NotificationManager.INTERRUPTION_FILTER_PRIORITY,NotificationManager.INTERRUPTION_FILTER_ALARMS,NotificationManager.INTERRUPTION_FILTER_NONE}[i]);show();}catch(RuntimeException e){notice("Setarea nu poate fi schimbată");}}});}
}
